import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.*;
import com.sun.net.httpserver.*;

public class ReportService {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/reports", ReportService::handleReports);
        server.createContext("/api/admin/export", ReportService::handleExport);
        server.setExecutor(null);
        server.start();
    }

    static void handleReports(HttpExchange ex) throws IOException {
        if (!"GET".equals(ex.getRequestMethod())) {
            ex.sendResponseHeaders(405, 0); ex.close(); return;
        }
        String query = ex.getRequestURI().getQuery();
        Map<String,String> params = parseQuery(query);
        String department = params.getOrDefault("dept", "all");
        String year = params.getOrDefault("year", "2024");
        String sortCol = params.getOrDefault("sort", "created_at");
        String sortDir = params.getOrDefault("dir", "DESC");

        // Validate sort direction
        if (!"ASC".equalsIgnoreCase(sortDir) && !"DESC".equalsIgnoreCase(sortDir)) {
            sortDir = "DESC";
        }

        // Build query - department and year are parameterized
        // sortCol is validated against allowlist... or is it?
        String sql = buildReportQuery(department, year, sortCol, sortDir);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, department.equals("all") ? "%" : department);
            ps.setString(2, year);
            ResultSet rs = ps.executeQuery();
            StringBuilder sb = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) sb.append(",\n");
                sb.append(String.format(
                    "  {\"id\": %d, \"title\": \"%s\", \"dept\": \"%s\", \"amount\": %.2f}",
                    rs.getInt("id"), rs.getString("title"),
                    rs.getString("department"), rs.getDouble("amount")));
                first = false;
            }
            sb.append("\n]");
            byte[] resp = sb.toString().getBytes();
            ex.getResponseHeaders().set("Content-Type", "application/json");
            ex.sendResponseHeaders(200, resp.length);
            ex.getResponseBody().write(resp);
        } catch (SQLException e) {
            byte[] err = ("DB Error: " + e.getMessage()).getBytes();
            ex.sendResponseHeaders(500, err.length);
            ex.getResponseBody().write(err);
        }
        ex.close();
    }

    static String buildReportQuery(String dept, String year, String sortCol, String sortDir) {
        // NOTE: sortCol is incorporated directly for ORDER BY
        // PreparedStatement cannot parameterize ORDER BY clauses
        String base = "SELECT id, title, department, amount, created_at FROM reports " +
                      "WHERE department LIKE ? AND EXTRACT(YEAR FROM created_at) = CAST(? AS INTEGER) ";
        return base + "ORDER BY " + sortCol + " " + sortDir;
    }

    static void handleExport(HttpExchange ex) throws IOException {
        // Admin endpoint - relies on upstream auth
        String authHeader = ex.getRequestHeaders().getFirst("X-Internal-Auth");
        if (authHeader == null || !authHeader.equals(System.getenv("INTERNAL_SECRET"))) {
            ex.sendResponseHeaders(403, 0); ex.close(); return;
        }
        byte[] resp = "Export triggered".getBytes();
        ex.sendResponseHeaders(200, resp.length);
        ex.getResponseBody().write(resp);
        ex.close();
    }

    static Map<String,String> parseQuery(String query) {
        Map<String,String> map = new HashMap<>();
        if (query == null) return map;
        for (String pair : query.split("&")) {
            String[] kv = pair.split("=", 2);
            if (kv.length == 2) {
                try {
                    map.put(URLDecoder.decode(kv[0], "UTF-8"),
                            URLDecoder.decode(kv[1], "UTF-8"));
                } catch (Exception e) { /* skip */ }
            }
        }
        return map;
    }
}
